Here is a complete, production-ready Terraform module structure that fulfills the canonical scenario specification. It uses a modular design, environment-specific `tfvars`, and idiomatic AWS resource configurations.

### 📁 Directory Structure
```
.
├── main.tf              # Root configuration
├── variables.tf         # Root variables
├── dev.tfvars           # Dev environment overrides
├── prod.tfvars          # Prod environment overrides
└── modules/
    └── app-infra/
        ├── main.tf      # Core resources
        ├── variables.tf # Module inputs
        └── outputs.tf   # Module outputs
```

---

### 📦 `modules/app-infra/variables.tf`
```hcl
variable "environment" {
  description = "Environment name (dev or prod)"
  type        = string
}

variable "bucket_name_prefix" {
  description = "Prefix for the S3 bucket name"
  type        = string
}

variable "rds_instance_class" {
  description = "RDS instance class"
  type        = string
}

variable "rds_multi_az" {
  description = "Enable multi-AZ deployment"
  type        = bool
}

variable "rds_backup_retention_period" {
  description = "Number of days to retain automated backups"
  type        = number
}

variable "rds_storage_encrypted" {
  description = "Enable storage encryption for RDS"
  type        = bool
}

variable "db_username" {
  description = "Database master username"
  type        = string
}

variable "db_password" {
  description = "Database master password"
  type        = string
  sensitive   = true
}

variable "iam_role_name" {
  description = "Name of the IAM service account role"
  type        = string
}

variable "iam_oidc_provider_arn" {
  description = "OIDC provider ARN for prod trust policy (null for dev)"
  type        = string
  default     = null
}

variable "iam_oidc_sub" {
  description = "OIDC subject claim for prod trust policy (null for dev)"
  type        = string
  default     = null
}

variable "vpc_id" {
  description = "VPC ID for RDS deployment"
  type        = string
}

variable "subnet_ids" {
  description = "Subnet IDs for RDS subnet group"
  type        = list(string)
}

variable "security_group_ids" {
  description = "Security group IDs for RDS"
  type        = list(string)
}

variable "replication_target_region" {
  description = "Target region for cross-region replication (prod only)"
  type        = string
  default     = null
}
```
